+package com.example;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final MessageStore store;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        name.setRequired(false);
+        email.setRequired(false);
+        phone.setRequired(false);
+        message.setRequired(false);
+        message.setWidthFull();
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        grid.setItems(store.newestFirst());
+
+        send.addClickListener(event -> submit());
+        send.addClickShortcut(Key.ENTER);
+        name.addValueChangeListener(event -> send.setEnabled(true));
+        email.addValueChangeListener(event -> send.setEnabled(true));
+        phone.addValueChangeListener(event -> send.setEnabled(true));
+        message.addValueChangeListener(event -> send.setEnabled(true));
+
+        add(name, email, phone, message, send, grid);
+    }
+
+    private void submit() {
+        boolean valid = true;
+        String nameValue = value(name);
+        String emailValue = email.getValue() == null ? "" : email.getValue();
+        String phoneValue = value(phone);
+        String messageValue = value(message);
+
+        name.setInvalid(nameValue.isBlank());
+        name.setErrorMessage("Name is required");
+        valid &= !nameValue.isBlank();
+
+        boolean badEmail = !emailValue.isBlank() && !emailValue.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+        email.setInvalid(badEmail || (emailValue.isBlank() && phoneValue.isBlank()));
+        email.setErrorMessage(badEmail ? "Enter a valid e-mail address" : "Give an e-mail address or a phone number");
+        valid &= !badEmail && !(emailValue.isBlank() && phoneValue.isBlank());
+
+        boolean blankMessage = messageValue.isBlank();
+        boolean longMessage = messageValue.length() > 500;
+        message.setInvalid(blankMessage || longMessage);
+        message.setErrorMessage(blankMessage ? "Message is required" : "Message must be at most 500 characters");
+        valid &= !blankMessage && !longMessage;
+
+        if (!valid) return;
+
+        ContactMessage sent = new ContactMessage(nameValue, emailValue, phoneValue, messageValue);
+        store.add(sent);
+        grid.setItems(store.newestFirst());
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private static String value(TextField field) {
+        return field.getValue() == null ? "" : field.getValue();
+    }
+
+    private static String value(TextArea field) {
+        return field.getValue() == null ? "" : field.getValue();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (value(name).isEmpty() && (email.getValue() == null || email.getValue().isEmpty()) && value(phone).isEmpty() && value(message).isEmpty()) return;
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.add("You have an unsent message. Discard it?");
+        Button keep = new Button("Keep editing", e -> {
+            dialog.close();
+            navigation.cancel();
+        });
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(keep, discard);
+        dialog.open();
+    }
+}
